const http = require("node:http");
const fs = require("node:fs");
const path = require("node:path");

const port = Number(process.env.PORT || 4701);
const notes = [];

function json(response, status, body) {
  response.writeHead(status, { "content-type": "application/json" });
  response.end(JSON.stringify(body));
}

http
  .createServer((request, response) => {
    if (request.url === "/" || request.url === "/index.html") {
      response.writeHead(200, { "content-type": "text/html; charset=utf-8" });
      response.end(fs.readFileSync(path.join(__dirname, "public/index.html")));
      return;
    }
    if (request.url === "/api/notes" && request.method === "GET") {
      json(response, 200, notes);
      return;
    }
    json(response, 404, { error: "not found" });
  })
  .listen(port, "127.0.0.1", () => console.log(`listening on ${port}`));

CREATE TABLE IF NOT EXISTS notes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  text TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

const http = require("node:http");
const fs = require("node:fs");
const path = require("node:path");
const { DatabaseSync } = require("node:sqlite");

const port = Number(process.env.PORT || 4701);
fs.mkdirSync(path.join(__dirname, "data"), { recursive: true });
const db = new DatabaseSync(path.join(__dirname, "data/app.db"));
db.exec(fs.readFileSync(path.join(__dirname, "data/schema.sql"), "utf8"));

function json(response, status, body) {
  response.writeHead(status, { "content-type": "application/json" });
  response.end(JSON.stringify(body));
}

http
  .createServer((request, response) => {
    if (request.url === "/" || request.url === "/index.html") {
      response.writeHead(200, { "content-type": "text/html; charset=utf-8" });
      response.end(fs.readFileSync(path.join(__dirname, "public/index.html")));
      return;
    }
    if (request.url === "/api/notes" && request.method === "GET") {
      json(response, 200, db.prepare("SELECT id, text, created_at FROM notes ORDER BY id DESC").all());
      return;
    }
    if (request.url === "/api/notes" && request.method === "POST") {
      let body = "";
      request.on("data", (chunk) => (body += chunk));
      request.on("end", () => {
        let text = "";
        try {
          text = String(JSON.parse(body).text || "").trim();
        } catch {
          text = "";
        }
        if (!text) return json(response, 400, { error: "text is required" });
        const result = db.prepare("INSERT INTO notes (text) VALUES (?)").run(text);
        json(response, 201, { id: Number(result.lastInsertRowid), text });
      });
      return;
    }
    json(response, 404, { error: "not found" });
  })
  .listen(port, "127.0.0.1", () => console.log(`listening on ${port}`));
